def group_by(items: list, key_fn) -> dict:
    """Bucket items into {key: [items]} using key_fn(item) as the key."""
    buckets = {}
    for item in items:
        buckets.setdefault(key_fn(item), []).append(item)
    return buckets

print(group_by(['ant', 'bee', 'bear'], lambda s: s[0]))
